/**
 * The list-readiness flag-off golden (READ_API_LIST_READINESS_ENABLED): a fixed set of GET /v1/sessions (plain,
 * filtered, cursor, q, q cursor, includeShortSummary) and /v1/sessions/activity requests, through createReadApi and
 * the real sqlDirectory over a recording tenant runner with canned rows. Every SQL statement and its parameters,
 * every status, content type and response body are recorded.
 *
 * Uses only APIs that exist before list readiness, so the same file runs unchanged on the base commit:
 * fixtures/list-readiness-flag-off.golden.json was generated by running this harness on origin/main
 * (7e4f881e8ed4c233531423558597ee71903b3f93), not by the code under test. Regenerate it only from a base commit:
 *   bun -e 'import { goldenRecord } from "./src/session-read-api/__tests__/list-readiness-golden-harness.ts";
 *           console.log(JSON.stringify(await goldenRecord({}), null, 2))'
 */
import { createReadApi } from "../app.ts";
import { sqlDirectory } from "../directory.ts";
import type { TenantRunner } from "../liveness.ts";
import { memoryLiveness } from "./support.ts";

export interface GoldenEntry {
  request: string;
  status: number;
  contentType: string | null;
  body: string;
  statements: Array<{ text: string; params: unknown[] }>;
}

const ROW = (session: string, cursorTs: string) => ({
  org_id: "org-a", workspace_id: "ws-a", harness: "codex", session_id: session,
  created_at: new Date("2026-10-01T00:00:00Z"), last_activity_at: new Date(cursorTs),
  cursor_ts: cursorTs,
  title: `Title ${session}`, task_title: "Fix the thing", agent_names: ["Lead"], project_id: "github.com/acme/api",
  project_key: null, project_key_method: null, git_repo: null, git_branch: null, initial_commit: null,
  originator: null, agent_version: null, models: ["gpt-5"], state: "active", event_count: "12",
  input_tokens: "100", output_tokens: 7, cost_usd_micros: null, machine_ids: ["m-1"], user_ids: ["u-1"],
  parent_session_ids: [], child_session_count: 0, short_summary: "Recorded summary", short_summary_generated_at: new Date("2026-10-03T00:00:00Z"),
  catalog_projected_at: new Date("2026-10-03T00:00:00Z"), projected_at: new Date("2026-10-03T00:00:00Z"),
});
const ROWS = [ROW("s-3", "2026-10-05T12:00:00.123456Z"), ROW("s-2", "2026-10-04T12:00:00.000001Z"), ROW("s-1", "2026-10-03T12:00:00Z")];

const W = "workspace=ws-a";
const BOUNDS = "lastTsAfter=2026-09-01T00:00:00Z&lastTsBefore=2026-11-01T00:00:00Z&firstTsAfter=2026-09-01T00:00:00Z&firstTsBefore=2026-11-01T00:00:00Z";
/** `NEXT` is replaced by the previous response's nextCursor. */
export const GOLDEN_REQUESTS = [
  `/v1/sessions?${W}`,
  `/v1/sessions?${W}&limit=2`,
  `/v1/sessions?${W}&limit=2&cursor=NEXT`,
  `/v1/sessions?${W}&limit=2&source=codex&notSource=claude&user=u-1&agent=Lead&projectContains=acme&${BOUNDS}`,
  `/v1/sessions?${W}&limit=2&source=codex&notSource=claude&user=u-1&agent=Lead&projectContains=acme&${BOUNDS}&cursor=NEXT`,
  `/v1/sessions?${W}&limit=2&includeShortSummary=recorded`,
  `/v1/sessions?${W}&limit=2&q=${encodeURIComponent("hello world -draft source:codex")}`,
  `/v1/sessions?${W}&limit=2&q=${encodeURIComponent("hello world -draft source:codex")}&cursor=NEXT`,
  `/v1/sessions?${W}&limit=2&q=${encodeURIComponent("hello")}&source=codex&user=u-1&${BOUNDS}`,
  `/v1/sessions?${W}&limit=2&q=${encodeURIComponent("hello")}&source=codex&user=u-1&${BOUNDS}&cursor=NEXT`,
  `/v1/sessions?${W}&limit=2&cursor=b96s1:not-a-cursor`,
  `/v1/sessions?${W}&limit=2&cursor=sessions-v2:abc`,
  `/v1/sessions/activity?${W}&since=2026-10-01T00:00:00Z&until=2026-10-07T00:00:00Z`,
];

/** Run GOLDEN_REQUESTS with these extra deps (e.g. `{ listReadiness: true }`); everything else fixed. */
export async function goldenRecord(extra: Record<string, unknown>): Promise<GoldenEntry[]> {
  let statements: Array<{ text: string; params: unknown[] }> = [];
  const run: TenantRunner = async (_org, _ws, work) => work({
    async query<R>(text: string, params?: unknown[]) {
      statements.push({ text, params: JSON.parse(JSON.stringify(params ?? [])) });
      if (text.includes("to_regprocedure")) return { rows: [{ installed: true }] as R[] };
      if (text.includes("activity_for")) return { rows: [{ day: "2026-10-03", harness: "codex", sessions: 2 }] as R[] };
      return { rows: ROWS as unknown as R[] };
    },
  });
  const app = createReadApi({
    verify: async () => ({ userId: "u-1", orgId: "org-a", workspaceId: "ws-a", scopes: ["rth:read"] }),
    ch: {} as never,
    liveness: memoryLiveness().liveness,
    completeSinceMs: 0,
    directory: sqlDirectory(run),
    directoryWorkspaces: new Set(["ws-a"]),
    sessionQuery: true,
    listShortSummary: true,
    ...extra,
  } as never);
  const out: GoldenEntry[] = [];
  let next: string | null = null;
  for (const template of GOLDEN_REQUESTS) {
    statements = [];
    const request = template.replace("NEXT", encodeURIComponent(next ?? ""));
    const r = await app.request(request, { headers: { authorization: "Bearer t", "x-correlation-id": "golden-1" } });
    const body = await r.text();
    try {
      next = (JSON.parse(body) as { nextCursor?: string | null }).nextCursor ?? next;
    } catch {
      // not JSON
    }
    out.push({ request, status: r.status, contentType: r.headers.get("content-type"), body, statements });
  }
  return out;
}
